namespace OoBDev.DevTerm;

/// <summary>The classic TCP services <see cref="ServiceHostBridge"/> can host.</summary>
public enum ServiceKind
{
    /// <summary>RFC 862: returns what it receives (port 7).</summary>
    Echo,

    /// <summary>RFC 863: swallows what it receives (port 9).</summary>
    Discard,

    /// <summary>RFC 867: answers any input with the local date and time (port 13).</summary>
    Daytime,

    /// <summary>RFC 868: answers any input with seconds since 1900 as four bytes (port 37).</summary>
    Time,

    /// <summary>RFC 864: streams generated bytes, capped per client (port 19).</summary>
    Chargen,
}
